import { SingletonProto } from 'egg';

@SingletonProto()
export class UserService {
  async getUser() { return 'hello'; }
}

import { SingletonProto } from 'egg';

@SingletonProto()
export class UserService {
  async findUser(id: string) {
    return { id, name: 'test' };
  }
}

import { SingletonProto, Inject } from 'egg';
import { UserService } from '../userModule/UserService.ts';

@SingletonProto()
export class OrderService {
  @Inject()
  userService: UserService;

  async createOrder(userId: string) {
    const user = await this.userService.findUser(userId);
    return { orderId: '1', user };
  }
}

import { SingletonProto } from 'egg';

export interface IFooService {
  doWork(): Promise<string>;
}

@SingletonProto()
export class FooService implements IFooService {
  async doWork() { return 'done'; }
}

import { SingletonProto, Inject } from 'egg';
import type { IFooService } from './FooService.ts';

@SingletonProto()
export class BarService {
  @Inject()
  fooHelper: IFooService;  // 期望注入 FooService

  async run() {
    return this.fooHelper.doWork();
  }
}

import { Service } from 'egg';

export default class OrderService extends Service {
  async create(data: any) {
    const user = await this.ctx.service.user.find(data.userId);
    this.ctx.logger.info('creating order for %s', user.name);
    const result = await this.app.httpclient.request('https://api.example.com/orders', {
      method: 'POST',
      data,
    });
    return result.data;
  }
}

import { SingletonProto, Inject } from 'egg';

@SingletonProto()
export class MixedService {
  @Inject()
  logger: Logger;

  constructor(
    @Inject() readonly config: EggAppConfig,
  ) {}

  async run() {
    this.logger.info('config: %j', this.config);
  }
}

