import { ImplDecorator, QualifierImplDecoratorUtil } from 'egg';
import { NotifyType } from '../NotifyType.ts';
import { AbstractNotifier } from '../AbstractNotifier.ts';

export const NOTIFY_ATTRIBUTE = Symbol('NOTIFY_ATTRIBUTE');

export const Notify: ImplDecorator<AbstractNotifier, typeof NotifyType> =
  QualifierImplDecoratorUtil.generatorDecorator(AbstractNotifier, NOTIFY_ATTRIBUTE);

import { Notify } from '../decorator/Notify.ts';
import { NotifyType } from '../NotifyType.ts';
import { AbstractNotifier } from '../AbstractNotifier.ts';

@Notify(NotifyType.EMAIL)
export class EmailNotifier extends AbstractNotifier {
  async send(msg: string) {
    console.log('send email:', msg);
  }
}
